Author: Eduardo Silva <eduardo@treasure-data.com>
Date:   Mon Oct 12 20:51:33 2020 -0600

    pack: gelf: on flatten, only process string key types (oss-fuzz 26294)

    Signed-off-by: Eduardo Silva <eduardo@treasure-data.com>

diff --git a/src/flb_pack_gelf.c b/src/flb_pack_gelf.c
index e90e0fe69..1a4007232 100644
--- a/src/flb_pack_gelf.c
+++ b/src/flb_pack_gelf.c
@@ -224,200 +224,204 @@ static flb_sds_t flb_msgpack_gelf_flatten(flb_sds_t *s, msgpack_object *o,
         if (tmp == NULL) {
             return NULL;
         }
         *s = tmp;
         break;

     case MSGPACK_OBJECT_NEGATIVE_INTEGER:
         tmp = flb_sds_printf(s, "%ld", (signed long)o->via.i64);
         if (tmp == NULL) {
             return NULL;
         }
         *s = tmp;
         break;

     case MSGPACK_OBJECT_FLOAT32:
     case MSGPACK_OBJECT_FLOAT64:
         tmp = flb_sds_printf(s, "%f", o->via.f64);
         if (tmp == NULL) {
             return NULL;
         }
         *s = tmp;
         break;

     case MSGPACK_OBJECT_STR:
         tmp = flb_msgpack_gelf_value(s, !in_array,
                                      o->via.str.ptr,
                                      o->via.str.size);
         if (tmp == NULL) {
             return NULL;
         }
         *s = tmp;
         break;

     case MSGPACK_OBJECT_BIN:
         tmp = flb_msgpack_gelf_value(s, !in_array,
                                      o->via.bin.ptr,
                                      o->via.bin.size);
         if (tmp == NULL) {
             return NULL;
         }
         *s = tmp;
         break;

     case MSGPACK_OBJECT_EXT:
         tmp = flb_msgpack_gelf_value_ext(s, !in_array,
                                          o->via.ext.ptr,
                                          o->via.ext.size);
         if (tmp == NULL) {
             return NULL;
         }
         *s = tmp;
         break;

     case MSGPACK_OBJECT_ARRAY:
         loop = o->via.array.size;

         if (!in_array) {
             tmp = flb_sds_cat(*s, "\"", 1);
             if (tmp == NULL) {
                 return NULL;
             }
             *s = tmp;
         }
         if (loop != 0) {
             msgpack_object* p = o->via.array.ptr;
             for (i=0; i<loop; i++) {
                 if (i > 0) {
                      tmp = flb_sds_cat(*s, ", ", 2);
                      if (tmp == NULL) {
                          return NULL;
                      }
                      *s = tmp;
                 }
                 tmp = flb_msgpack_gelf_flatten(s, p+i,
                                                prefix, prefix_len,
                                                FLB_TRUE);
                 if (tmp == NULL) {
                     return NULL;
                 }
                 *s = tmp;
             }
         }

         if (!in_array) {
             tmp = flb_sds_cat(*s, "\"", 1);
             if (tmp == NULL) {
                 return NULL;
             }
             *s = tmp;
         }
         break;

     case MSGPACK_OBJECT_MAP:
         loop = o->via.map.size;
         if (loop != 0) {
             msgpack_object_kv *p = o->via.map.ptr;
             for (i = 0; i < loop; i++) {
                 msgpack_object *k = &((p+i)->key);
                 msgpack_object *v = &((p+i)->val);

+                if (k->type != MSGPACK_OBJECT_STR) {
+                    continue;
+                }
+
                 const char *key = k->via.str.ptr;
                 int key_len = k->via.str.size;

                 if (v->type == MSGPACK_OBJECT_MAP) {
                     char *obj_prefix = NULL;
                     int obj_prefix_len = 0;

                     obj_prefix_len = key_len;
                     if (prefix_len > 0) {
                         obj_prefix_len += prefix_len + 1;
                     }

                     obj_prefix = flb_malloc(obj_prefix_len + 1);
                     if (obj_prefix == NULL) {
                        return NULL;
                     }

                     if (prefix_len > 0) {
                         memcpy(obj_prefix, prefix, prefix_len);
                         obj_prefix[prefix_len] = '_';
                         memcpy(obj_prefix + prefix_len + 1, key, key_len);
                     }
                     else {
                         memcpy(obj_prefix, key, key_len);
                     }
                     obj_prefix[obj_prefix_len] = '\0';

                     tmp = flb_msgpack_gelf_flatten(s, v,
                                                    obj_prefix, obj_prefix_len,
                                                    in_array);
                     if (tmp == NULL) {
                         flb_free(obj_prefix);
                         return NULL;
                     }
                     *s = tmp;

                     flb_free(obj_prefix);
                 }
                 else {
                     if (in_array == FLB_TRUE && i > 0) {
                         tmp = flb_sds_cat(*s, " ", 1);
                         if (tmp == NULL) {
                             return NULL;
                         }
                         *s = tmp;
                     }
                     if (in_array && prefix_len <= 0) {
                         tmp = flb_msgpack_gelf_key(s, in_array,
                                                    NULL, 0,
                                                    FLB_FALSE,
                                                    key, key_len);
                     }
                     else {
                         tmp = flb_msgpack_gelf_key(s, in_array,
                                                    prefix, prefix_len,
                                                    FLB_TRUE,
                                                    key, key_len);
                     }
                     if (tmp == NULL) {
                         return NULL;
                     }
                     *s = tmp;

                     tmp = flb_msgpack_gelf_flatten(s, v, NULL, 0, in_array);
                     if (tmp == NULL) {
                         return NULL;
                     }
                     *s = tmp;
                 }
             }
         }
         break;

     default:
         flb_warn("[%s] unknown msgpack type %i", __FUNCTION__, o->type);
     }

     return *s;
 }

 flb_sds_t flb_msgpack_to_gelf(flb_sds_t *s, msgpack_object *o,
                               struct flb_time *tm,
                               struct flb_gelf_fields *fields)
 {
     int i;
     int loop;
     flb_sds_t tmp;

     int host_key_found = FLB_FALSE;
     int timestamp_key_found = FLB_FALSE;
     int level_key_found = FLB_FALSE;
     int short_message_key_found = FLB_FALSE;
     int full_message_key_found = FLB_FALSE;

     char *host_key = NULL;
     char *timestamp_key = NULL;
     char *level_key = NULL;
     char *short_message_key = NULL;
     char *full_message_key = NULL;
